'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={dashboard:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',customers:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-4a6 6 0 0 1 12 0v4M16 4a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 5v2"/>',orders:'<rect x="5" y="4" width="14" height="18" rx="2"/><path d="M9 2h6v4H9zM9 11h6m-6 4h6"/>',production:'<rect x="3" y="4" width="4" height="16" rx="1"/><rect x="10" y="4" width="4" height="10" rx="1"/><rect x="17" y="4" width="4" height="13" rx="1"/>',measurements:'<rect x="3" y="7" width="18" height="10" rx="2"/><path d="M7 7v5m5-5v3m5-3v5"/>',creations:'<path d="M9 5a3 3 0 1 1 4 3v3l8 7a1 1 0 0 1-1 2H4a1 1 0 0 1-1-2l10-7"/>',payments:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 10h18m-5 5h2"/>',quotes:'<path d="M6 3h12v19l-3-2-3 2-3-2-3 2V3zM9 7h6m-6 4h6m-6 4h4"/>',website:'<rect x="2" y="4" width="20" height="16" rx="2"/><path d="M2 9h20m-16 4h6m-6 3h6"/>',settings:'<path d="M12 3l8 4v6c0 5-8 9-8 9s-8-4-8-9V7z"/><path d="m8 12 3 3 5-6"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',plus:'<path d="M12 4v16M4 12h16"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6m10-6v6M3 11h18m-13 4h4"/>',alert:'<path d="m12 3 10 18H2zM12 9v5m0 3v1"/>',print:'<path d="M7 8V3h10v5M7 18H3V9h18v9h-4M7 14h10v8H7z"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>'};
const ic=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.creations}</svg>`;
const initials=n=>String(n||'').split(' ').map(s=>s[0]).slice(0,2).join('');const avatar=c=>`<span class="avatar">${esc(initials(c.name))}</span>`;
const money=n=>'₹'+Number(n||0).toLocaleString('en-IN',{minimumFractionDigits:Number(n||0)%1?2:0,maximumFractionDigits:2});const cash=n=>Math.round(Number(n)*100)/100;
const date=d=>{if(!d)return 'Not set';const p=new Date(d+'T12:00:00');return Number.isNaN(p.getTime())?esc(d):p.toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'})};
const shortDate=d=>d?new Date(d+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short'}):'Not set';
const STORAGE='rr-creation-demo-v2';let db;let storageProblem=false;try{const raw=localStorage.getItem(STORAGE);if(raw){db=JSON.parse(raw);if(db.version!==2||!Array.isArray(db.orders)||!Array.isArray(db.customers))throw Error('Invalid stored workspace')}else{const old=JSON.parse(localStorage.getItem('knownstate-demo-v1')||'null');db=old?migrateLegacy(old):newSeed();localStorage.setItem(STORAGE,JSON.stringify(db))}}catch{db=newSeed();storageProblem=true}
let view='dashboard',currentId='',customerTab='overview',orderTab='details',filter='All',searchQuery='',versionIndex=0,toastTimer;
const isOwner=()=>$('#role').value==='Owner';const customer=id=>db.customers.find(c=>c.id===id);const order=id=>db.orders.find(o=>o.id===id);const total=o=>cash(o.lines.reduce((a,l)=>a+l.qty*l.rate,0));const paid=o=>cash(o.payments.reduce((a,p)=>a+p.amount,0));const balance=o=>cash(total(o)-paid(o));const active=o=>o.stage!=='Delivered';const overdue=o=>active(o)&&o.due<localDay();const custOrders=id=>db.orders.filter(o=>o.customer===id);const custBalance=id=>cash(custOrders(id).reduce((a,o)=>a+balance(o),0));
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify(db));return true}catch{toast('Storage is full or unavailable. This change lasts only until you close the page.');return false}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
function log(text,cid,oid){const entry={text,customer:cid||null,order:oid||null,date:localDay()};db.activity.unshift(entry);if(oid)order(oid)?.events.push({text,date:entry.date})}
function commit(message){const ok=persist();render();if(ok)toast(message)}
const pill=(s,cls='')=>`<span class="pill ${cls||({Confirmed:'gold',Cutting:'blue',Stitching:'purple',Fitting:'gold',Ready:'teal',Delivered:'teal',Pending:'gold','Follow up':'red',Ordered:'teal'}[s]||'')}">${esc(s)}</span>`;
const action=(label,act,id='',secondary=false,icon='plus')=>`<button class="btn ${secondary?'secondary':''}" data-action="${act}" data-id="${esc(id)}">${icon?ic(icon):''}${label}</button>`;
const empty=(title,sub='')=>`<div class="empty"><h3>${title}</h3>${sub}</div>`;
function heading(title,sub,actions=''){return `<div class="heading"><div><div class="eyebrow">RR CREATION / ${view==='dashboard'?'YOUR STUDIO, IN SYNC':view==='profile'?'CUSTOMER WORKSPACE':view.toUpperCase()}</div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`}
function activityList(list){return list.length?list.map(a=>`<div class="activity"><div><p>${esc(a.text)}</p><small>${date(a.date)} · ${a.staff||'Studio team'}</small></div></div>`).join(''):empty('The story starts here.','New activity will appear as you work.')}
function dueText(o){return o.stage==='Delivered'?'Collected '+shortDate(o.collected):o.due===localDay()?'Due today':(overdue(o)?'Overdue · ':'Due ')+shortDate(o.due)}
function ordersTable(list,compact=false){return list.length?`<div class="tablewrap"><table><thead><tr><th>Order / customer</th><th>Creation</th><th>Stage</th><th>Delivery</th>${!compact&&isOwner()?'<th>Balance</th>':''}<th></th></tr></thead><tbody>${list.map(o=>`<tr class="row-link"><td><a href="#order/${o.id}"><strong>${o.id}</strong><small>${esc(customer(o.customer)?.name)}</small></a></td><td><strong>${esc(o.lines[0]?.title)}</strong><small>${o.lines.reduce((s,l)=>s+l.qty,0)} piece${o.lines.reduce((s,l)=>s+l.qty,0)!==1?'s':''} · ${esc(o.tailor)}</small></td><td>${pill(o.stage)}</td><td><span class="${overdue(o)?'pill red':''}">${dueText(o)}</span></td>${!compact&&isOwner()?`<td class="money">${money(balance(o))}</td>`:''}<td><a class="link" href="#order/${o.id}" aria-label="Open order ${o.id}">↗</a></td></tr>`).join('')}</tbody></table></div>`:empty('No orders in this view.','Try another filter or create an order.')}
function dashboard(){const today=localDay(),live=db.orders.filter(active),del=live.filter(o=>o.due===today),fits=live.filter(o=>o.fitting===today),late=live.filter(overdue),unpaid=db.orders.filter(o=>balance(o)>0);const collectedToday=cash(db.orders.reduce((s,o)=>s+o.payments.filter(p=>p.date===today).reduce((a,p)=>a+p.amount,0),0));return heading('A beautiful day to create.',new Date().toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'long',year:'numeric'})+' · Salt Lake, Kolkata',action('New order','order'))+`<div class="overview-intro"><div><div class="eyebrow">THE ATELIER EDIT</div><h2>Every stitch has a story.<br>Every detail has a place.</h2><p>${live.length} creations in the making. ${db.orders.filter(o=>o.stage==='Ready').length} ready for their next chapter.</p></div><div class="intro-summary"><div><strong>${db.customers.length.toString().padStart(2,'0')}</strong><span>Customer stories</span></div><div><strong>${isOwner()?money(collectedToday):fits.length}</strong><span>${isOwner()?'Collected today':'Fittings today'}</span></div></div></div><div class="stats">${[['Deliveries today',del.length,'Ready for a memorable handover','calendar','today','good'],['Fittings today',fits.length,'The finishing touches matter','measurements','fittings',''],['Needs attention',late.length,'Orders beyond their promised date','alert','overdue','warn'],[isOwner()?'Outstanding balance':'Ready to collect',isOwner()?money(unpaid.reduce((s,o)=>s+balance(o),0)):db.orders.filter(o=>o.stage==='Ready').length,isOwner()?unpaid.length+' orders with a balance':'Finished and checked','payments',isOwner()?'unpaid':'Ready','']].map(([label,value,sub,icon,f,tone])=>`<button class="stat" data-route="orders/${f}"><div class="stat-top">${label}${ic(icon)}</div><strong>${value}</strong><small class="${tone}">${sub} ↗</small></button>`).join('')}</div><div class="grid"><div><section class="card"><div class="cardhead"><div><h2>On the cutting table</h2><p>The orders moving through your studio.</p></div><a class="link" href="#orders">All orders ↗</a></div>${ordersTable([...live].sort((a,b)=>a.due.localeCompare(b.due)).slice(0,5),true)}<div class="tablefoot">${live.length} active orders · Every stage, one connected workspace.</div></section><section class="card sectiongap"><div class="cardhead"><h2>A little attention goes a long way</h2><span class="pill gold">FOLLOW-UPS</span></div>${reminderRows().slice(0,3).map(r=>`<div class="attention"><span class="attention-icon">${ic(r.type==='quote'?'quotes':'clock')}</span><div><h3>${esc(r.name)}</h3><p>${esc(r.title)}</p></div><button class="link" data-action="reminder" data-id="${r.key}">Preview ↗</button></div>`).join('')||empty('All caught up.','There are no outstanding reminders.')}</section></div><div><section class="card"><div class="cardhead"><h2>Today at the atelier</h2><span class="pill">${shortDate(today)}</span></div>${[...fits.map(o=>({...o,kind:'Fitting'})),...del.map(o=>({...o,kind:'Delivery'}))].map((o,i)=>`<div class="schedule-row"><span class="time">${o.kind==='Fitting'?'FIT':'DUE'}</span><div><h3>${esc(customer(o.customer)?.name)}</h3><p>${esc(o.lines[0].title)}</p><small>${o.id} · ${o.kind}</small></div><a class="link" href="#order/${o.id}">↗</a></div>`).join('')||empty('A little breathing room.','No fittings or deliveries scheduled today.')}</section><section class="card sectiongap"><div class="cardhead"><h2>Hands behind the craft</h2><a class="link" href="#production">Board ↗</a></div>${TAILORS.map(t=>{const n=live.filter(o=>o.tailor===t).length;return `<a href="#orders/tailor:${encodeURIComponent(t)}" class="workload" style="display:block"><div class="row"><div class="person"><span class="avatar">${initials(t)}</span><strong>${t}</strong></div><small>${n} active</small></div><div class="bar"><span style="width:${Math.min(100,n/Math.max(live.length,1)*100)}%"></span></div></a>`}).join('')}</section></div></div>`}
function reminderRows(){return [...db.orders.filter(o=>active(o)&&(o.stage==='Ready'||overdue(o)||o.fitting===localDay())).map(o=>({key:'order:'+o.id,type:'order',name:customer(o.customer)?.name,title:o.stage==='Ready'?'Ready for collection · '+o.id:overdue(o)?'Delivery follow-up · '+o.id:'Fitting confirmation · '+o.id})),...(isOwner()?db.quotes.filter(q=>q.status!=='Ordered').map(q=>({key:'quote:'+q.id,type:'quote',name:customer(q.customer)?.name,title:'Quotation follow-up · '+q.title})):[]),...(db.legacyTasks||[]).filter(t=>!t.done).map(t=>({key:'legacy:'+t.id,type:'legacy',name:customer(t.customer)?.name,title:t.title}))].filter(r=>!db.doneReminders.includes(r.key))}
function customerTable(list){return list.length?`<div class="tablewrap"><table><thead><tr><th>Customer</th><th>Contact</th><th>Ledger no.</th><th>Latest fitting</th><th>${isOwner()?'Balance':'Orders'}</th><th></th></tr></thead><tbody>${list.map(c=>`<tr class="row-link"><td><a href="#customer/${c.id}${view==='measurements'?'/measurements':''}" class="person">${avatar(c)}<div><strong>${esc(c.name)}</strong><small>${c.id} · Since ${c.since}</small></div></a></td><td>${esc(c.phone||'Not recorded')}</td><td>${esc(c.ledger||'—')}</td><td>${c.measurements[0]?shortDate(c.measurements[0].date):'Not measured'}</td><td>${isOwner()?money(custBalance(c.id)):custOrders(c.id).length}</td><td><a class="link" href="#customer/${c.id}${view==='measurements'?'/measurements':''}">Open ↗</a></td></tr>`).join('')}</tbody></table></div>`:empty('No matching customers.','Search a different name, phone or ledger number.')}
function customersPage(){return heading(view==='measurements'?'A perfect fit starts here.':'People behind every piece.',view==='measurements'?'Open a customer to record or compare the complete RR Creation measurement sheet.':'Every fit, preference and conversation, beautifully remembered.',action('Add customer','customer'))+`<div class="filterbar"><label class="inline-search">${ic('search')}<input id="customer-search" aria-label="Search customer directory" placeholder="Name, phone, UID or ledger number"></label><small>${db.customers.length} customer records</small></div><section class="card"><div id="customer-results">${customerTable(db.customers)}</div></section>`}
function measureTable(m,prev,group,unit=m?.unit||'in'){const fields=group==='upper'?UPPER:SALWAR;return `<table class="measure-table"><thead><tr><th>Measurement</th><th>${m?shortDate(m.date):'Latest'} · ${unit}</th><th>${prev?shortDate(prev.date):'Previous'}</th></tr></thead><tbody>${fields.map(n=>{let val=m?.[group]?.[n],old=prev?.[group]?.[n];const convert=v=>v==null||v===''?'':cash(Number(v)*(m.unit===unit?1:unit==='cm'?2.54:1/2.54));if(m)val=convert(val);if(old!=null&&old!=='')old=cash(Number(old)*(prev.unit===unit?1:unit==='cm'?2.54:1/2.54));const diff=val!==''&&val!=null&&old!==''&&old!=null?cash(val-old):0;return `<tr><td>${n}</td><td>${val==null||val===''?'—':val}${diff?`<small>${diff>0?'+':''}${diff}</small>`:''}</td><td>${old==null||old===''?'—':old}</td></tr>`}).join('')}</tbody></table>`}
function measurementPane(c){const m=c.measurements[versionIndex],prev=c.measurements[versionIndex+1];return `<div class="versionbar"><label>Fitting record <select id="measurement-version">${c.measurements.map((m,i)=>`<option value="${i}" ${i===versionIndex?'selected':''}>${date(m.date)} · ${esc(m.garment)}${i===0?' · Latest':''}</option>`).join('')}</select></label><div class="actions">${action('New fitting','measurement',c.id,false,'plus')}${action('Print sheet','print-measure',c.id,true,'print')}</div></div>${m?`<div class="snapshot-label">${ic('measurements')}Recorded by ${esc(m.staff)} · ${esc(m.unit)} · Previous values converted to the same unit for comparison.</div><div class="measure-grid"><section class="card"><div class="cardhead"><h2>Upper garment</h2><small>14 measurements</small></div>${measureTable(m,prev,'upper')}</section><section class="card"><div class="cardhead"><h2>Salwar</h2><small>8 measurements</small></div>${measureTable(m,prev,'salwar')}<div class="cardbody"><div class="note"><b>FITTING NOTES</b>${esc(m.notes||'No additional fitting notes.')}</div></div></section></div>`:empty('No measurements recorded yet.','Start the first fitting using the button above.')}<p class="muted sectiongap" style="font-size:12px">Labels match the paper sheet. Pointing, Down, Thai, Cluff and Fog are retained as printed.</p>`}
function profile(){const c=customer(currentId);if(!c)return empty('Customer not found.');const orders=custOrders(c.id),latest=c.measurements[0],next=orders.filter(active).sort((a,b)=>a.due.localeCompare(b.due))[0];return `<div class="heading"><a class="link" href="#customers">← Customer directory</a><div class="actions">${action('Edit profile','edit-customer',c.id,true,'')}${action('Repeat / new order','order',c.id)}</div></div><section class="card"><div class="profile-cover">${avatar(c)}<div><h1>${esc(c.name)}</h1><p>${esc(c.phone||'Phone not recorded')} · Customer since ${c.since}</p></div><div class="profile-id"><b>${c.id}</b><small>Ledger ${esc(c.ledger||'not linked')}</small></div></div><div class="profile-strip"><div><small>ACTIVE CREATIONS</small><strong>${orders.filter(active).length} orders</strong></div><div><small>NEXT DELIVERY</small><strong>${next?shortDate(next.due):'Nothing scheduled'}</strong></div><div><small>LATEST FITTING</small><strong>${latest?shortDate(latest.date):'Not recorded'}</strong></div><div><small>${isOwner()?'OUTSTANDING':'FITTING RECORDS'}</small><strong>${isOwner()?money(custBalance(c.id)):c.measurements.length}</strong></div></div></section><div class="tabs">${['overview','measurements','orders','creations',...(isOwner()?['payments']:[]),'activity'].map(t=>`<button data-tab="${t}" class="${customerTab===t?'active':''}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div>${customerTab==='measurements'?measurementPane(c):customerTab==='orders'?`<section class="card">${ordersTable(orders)}</section>`:customerTab==='creations'?`<div class="row" style="margin-bottom:20px"><h2>Her creation archive</h2>${action('Add creation','creation',c.id)}</div>${creationsGrid(db.creations.filter(x=>x.customer===c.id))}`:customerTab==='payments'?paymentsPage(c.id,true):customerTab==='activity'?`<section class="card">${activityList(db.activity.filter(a=>a.customer===c.id))}</section>`:`<div class="grid"><div><section class="card"><div class="cardhead"><h2>In the making</h2><button class="link" data-tab="orders">All orders ↗</button></div>${ordersTable(orders.filter(active),true)}</section><section class="card sectiongap"><div class="cardhead"><h2>Her fit, at a glance</h2><button class="link" data-tab="measurements">Full measurement sheet ↗</button></div>${latest?`<div class="profile-strip">${['Chest','Waist','Shoulder','Hand Length'].map(n=>`<div><small>${n.toUpperCase()}</small><strong>${latest.upper[n]??'—'} ${latest.unit}</strong></div>`).join('')}</div>`:empty('No fitting recorded yet.')}<div class="cardbody"><div class="note"><b>PREFERENCES TO REMEMBER</b>${esc(c.notes||'Add a few details about her preferred fit.')}</div></div></section></div><div><section class="card"><div class="cardhead"><h2>The next best step</h2></div><div class="cardbody"><p class="muted">${next?`${esc(next.lines[0].title)} is ${next.stage.toLowerCase()}. Delivery is promised for ${date(next.due)}.`:'Begin a new creation using this customer’s saved fit.'}</p><div class="actions sectiongap">${next?`<a class="btn" href="#order/${next.id}">Open ${next.id} ${ic('arrow')}</a>`:action('Create an order','order',c.id)}</div></div></section><section class="card sectiongap"><div class="cardhead"><h2>Recent moments</h2></div>${activityList(db.activity.filter(a=>a.customer===c.id).slice(0,4))}</section></div></div>`}`}
function filteredOrders(){return db.orders.filter(o=>{if(filter==='All')return true;if(filter==='today')return active(o)&&o.due===localDay();if(filter==='fittings')return active(o)&&o.fitting===localDay();if(filter==='overdue')return overdue(o);if(filter==='unpaid')return isOwner()&&balance(o)>0;if(filter.startsWith('tailor:'))return active(o)&&o.tailor===filter.slice(7);return o.stage===filter})}
function ordersPage(){const title={today:'Deliveries today',fittings:'Fittings today',overdue:'Orders needing attention',unpaid:'Outstanding orders'}[filter]||'Every creation, from start to finish.';return heading(title,'A clear path from the first measurement to the final handover.',action('New order','order'))+`<div class="filterbar"><div class="filters">${['All',...STAGES,'overdue'].map(f=>`<button data-filter="${f}" class="${filter===f?'active':''}">${f==='overdue'?'Overdue':f}</button>`).join('')}</div><a class="link" href="#production">Production board ↗</a></div>${filter.startsWith('tailor:')?`<p class="muted" style="margin-bottom:18px">Assigned to ${esc(filter.slice(7))}</p>`:''}<section class="card">${ordersTable(filteredOrders())}</section>`}
function production(){return heading('From a promise to a perfect fit.','Move a job forward from its order detail. Every change updates the studio.',action('New order','order'))+`<div class="board" tabindex="0" aria-label="Production stages, scroll horizontally to see all six stages">${STAGES.map(s=>`<section class="lane"><div class="lanehead"><span class="stage-dot"></span>${s}<span>${db.orders.filter(o=>o.stage===s).length}</span></div>${db.orders.filter(o=>o.stage===s).map(o=>`<a href="#order/${o.id}" class="job" style="display:block"><div class="row"><span class="job-id">${o.id}</span>${o.alterations.length?pill('Alteration','gold'):''}</div><h3>${esc(o.lines[0].title)}</h3><p>${esc(customer(o.customer)?.name)}</p><div class="job-footer ${overdue(o)?'overdue':''}"><span>${dueText(o)}</span><span class="mini-avatar" title="${o.tailor}">${initials(o.tailor)}</span></div></a>`).join('')||'<p class="muted" style="font-size:12px;padding:10px">No jobs at this stage.</p>'}</section>`).join('')}</div>`}
function orderPage(){const o=order(currentId);if(!o)return empty('Order not found.');const c=customer(o.customer),idx=STAGES.indexOf(o.stage);return `<div class="heading"><div><a class="link" href="#orders">← All orders</a><h1 style="margin-top:14px">${o.id} <span style="font:18px Georgia;color:#98a68e">/ ${esc(c?.name)}</span></h1><p>${esc(o.lines[0].title)} · ${o.lines.reduce((s,l)=>s+l.qty,0)} piece(s) · ${pill(o.stage)}</p></div><div class="actions">${action('Job sheet','job-sheet',o.id,true,'print')}${isOwner()?action('Invoice','invoice',o.id,true,'quotes'):''}${idx<5?action('Move to '+STAGES[idx+1],'stage',o.id,false,'arrow'):''}</div></div><div class="timeline">${STAGES.map((s,i)=>`<div class="stage-step ${i<idx?'done':i===idx?'current':''}"><span>${i<idx?'✓':String(i+1).padStart(2,'0')}</span>${s}</div>`).join('')}</div><div class="grid"><div><section class="card"><div class="cardhead"><h2>The making of this piece</h2><button class="link" data-action="edit-order" data-id="${o.id}">Edit job details ↗</button></div><div class="cardbody"><dl class="detail-list"><div><dt>Customer</dt><dd><a class="link" href="#customer/${c?.id}">${esc(c?.name)} ↗</a></dd></div><div><dt>Assigned tailor</dt><dd>${esc(o.tailor)}</dd></div><div><dt>Order date</dt><dd>${date(o.date)}</dd></div><div><dt>Promised delivery</dt><dd>${date(o.due)} ${overdue(o)?pill('Overdue','red'):''}</dd></div><div><dt>Fitting appointment</dt><dd>${date(o.fitting)}</dd></div><div><dt>Fabric source</dt><dd>${esc(o.fabricOwner)}</dd></div><div class="full"><dt>Fabric & design</dt><dd>${esc(o.fabric)}</dd></div></dl><div class="note sectiongap"><b>MAKE IT JUST RIGHT</b>${esc(o.notes||'No additional notes.')}</div></div><div class="tablewrap"><table><thead><tr><th>Particulars</th><th>Qty</th>${isOwner()?'<th>Rate</th><th>Amount</th>':''}</tr></thead><tbody>${o.lines.map(l=>`<tr><td>${esc(l.title)}</td><td>${l.qty}</td>${isOwner()?`<td>${money(l.rate)}</td><td>${money(l.qty*l.rate)}</td>`:''}</tr>`).join('')}</tbody></table></div></section><section class="card sectiongap"><div class="cardhead"><h2>Measurements for this order</h2>${pill('LOCKED SNAPSHOT','teal')}</div><div class="cardbody"><div class="snapshot-label">${ic('settings')}Captured ${o.snapshot?date(o.snapshot.date):'without measurements'}. Future fittings won’t change this job.</div>${o.snapshot?`<div class="row"><p class="muted">${esc(o.snapshot.garment)} · ${o.snapshot.unit} · ${esc(o.snapshot.staff)}</p><button class="link" data-action="snapshot" data-id="${o.id}">View all 22 fields ↗</button></div>`:empty('No fitting was selected.','The job sheet explicitly marks the measurements as not recorded.')}</div></section><section class="card sectiongap"><div class="cardhead"><h2>Design references</h2><button class="link" data-action="reference" data-id="${o.id}">Add image ↗</button></div><div class="cardbody">${o.references.length?`<div class="refgrid">${o.references.map(r=>`<figure><a href="${r.data}" target="_blank" rel="noopener"><img src="${r.data}" alt="${esc(r.name)}"></a><figcaption>${esc(r.name)}</figcaption></figure>`).join('')}</div>`:'<div class="reference-empty">Keep neckline, fabric and embroidery references with the job.<br>Upload a JPG, PNG or WebP to this browser.</div>'}</div></section></div><div>${isOwner()?`<section class="financial"><div class="row"><h2>The balance of things</h2>${ic('payments')}</div><div class="balance money">${money(balance(o))}</div><p>${balance(o)>0?'Remaining to be collected':'Paid in full · ready for a happy handover'}</p><div class="row"><span>Order total</span><b>${money(total(o))}</b></div><div class="row"><span>Payments received</span><b>${money(paid(o))}</b></div>${balance(o)>0?action('Record payment','payment',o.id,false,'plus'):''}</section>`:''}<section class="card sectiongap"><div class="cardhead"><h2>Fitting & alterations</h2></div><div class="cardbody">${o.alterations.length?o.alterations.map(a=>`<div class="note" style="margin-bottom:12px"><b>${date(a.date)} · ${esc(a.stage)}</b>${esc(a.note)}</div>`).join(''):'<p class="muted">Small adjustments make a piece truly hers.</p>'}<div class="actions sectiongap">${action('Record alteration','alteration',o.id,true,'measurements')}</div></div></section><section class="card sectiongap"><div class="cardhead"><h2>Order journey</h2><button class="link" data-action="reminder" data-id="order:${o.id}">Reminder ↗</button></div>${activityList([...o.events].reverse())}</section></div></div>`}
function paymentTable(orders){const list=orders.flatMap(o=>o.payments.map(p=>({...p,order:o.id,customer:o.customer}))).sort((a,b)=>b.date.localeCompare(a.date));return list.length?`<div class="tablewrap"><table><thead><tr><th>Payment / customer</th><th>Order</th><th>Date</th><th>Method</th><th>Amount</th></tr></thead><tbody>${list.map(p=>`<tr><td><strong>${esc(customer(p.customer)?.name)}</strong><small>${esc(p.reference||p.id)}</small></td><td><a class="link" href="#order/${p.order}">${p.order}</a></td><td>${date(p.date)}</td><td>${esc(p.method)}</td><td>${money(p.amount)}</td></tr>`).join('')}</tbody></table></div>`:empty('No payments recorded.')}
function paymentsPage(cid=null,inline=false){if(!isOwner())return empty('Owner preview required.');const list=cid?custOrders(cid):db.orders;return (inline?'':heading('Every rupee, accounted for.','Record demo payments and keep every customer balance connected.'))+`<div class="stats payments-stats" style="grid-template-columns:repeat(3,1fr)">${[['Order value',list.reduce((s,o)=>s+total(o),0)],['Received',list.reduce((s,o)=>s+paid(o),0)],['Outstanding',list.reduce((s,o)=>s+balance(o),0)]].map(([n,v])=>`<div class="stat"><div class="stat-top">${n}</div><strong>${money(v)}</strong><small>Across ${list.length} orders</small></div>`).join('')}</div><section class="card"><div class="cardhead"><h2>Invoices & balances</h2><small>Simulated payments only</small></div><div class="tablewrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Total</th><th>Paid</th><th>Balance</th><th></th></tr></thead><tbody>${list.map(o=>`<tr><td><a class="link" href="#order/${o.id}">${o.id}</a></td><td>${esc(customer(o.customer)?.name)}</td><td>${money(total(o))}</td><td>${money(paid(o))}</td><td>${balance(o)>0?money(balance(o)):pill('Paid','teal')}</td><td><div class="actions"><button class="link" data-action="invoice" data-id="${o.id}">Invoice</button>${balance(o)>0?`<button class="link" data-action="payment" data-id="${o.id}">+ Payment</button>`:''}</div></td></tr>`).join('')}</tbody></table></div></section><section class="card sectiongap"><div class="cardhead"><h2>Payment history</h2></div>${paymentTable(list)}</section>`}
function creationsGrid(list){return list.length?`<div class="gallery">${list.map(c=>`<article class="card creation"><div class="creation-image">${c.image?`<img src="${c.image}" alt="${esc(c.title)}">`:ic('creations')}</div><div class="eyebrow">${esc(c.fabric)}</div><h2>${esc(c.title)}</h2><p>${esc(c.notes)}</p><div class="row"><a class="link" href="#customer/${c.customer}">${esc(customer(c.customer)?.name)} ↗</a>${pill(c.type,'teal')}</div><small style="display:block;margin-top:15px">${date(c.date)}${c.image?'':' · Sample record · no photograph'}</small></article>`).join('')}</div>`:empty('A new chapter is waiting.','Add the first creation to this customer’s archive.')}
function quotesPage(){return heading('Today’s idea. Tomorrow’s favourite.','Every estimate stays with its customer.',action('New quotation','quote'))+`<section class="card"><div class="tablewrap"><table><thead><tr><th>Quotation</th><th>Customer</th><th>Amount</th><th>Status</th><th></th></tr></thead><tbody>${db.quotes.map(q=>`<tr><td><strong>${esc(q.title)}</strong><small>${esc(q.id)} · ${date(q.date)}</small></td><td>${esc(customer(q.customer)?.name)}</td><td>${money(q.amount)}</td><td>${pill(q.status)}</td><td>${q.order?`<a class="link" href="#order/${q.order}">Open order ↗</a>`:q.status!=='Ordered'?`<button class="link" data-action="quote-order" data-id="${q.id}">Create order ↗</button>`:'Confirmed in previous demo'}</td></tr>`).join('')}</tbody></table></div></section>`}
function settingsPage(){return heading('A studio that works your way.','Business details, printed terms and a transparent demo activity log.')+`<div class="grid"><section class="card"><div class="cardhead"><h2>RR Creation · Business details</h2>${isOwner()?'<button class="link" data-action="settings">Edit settings ↗</button>':''}</div><div class="cardbody"><div class="note"><b>VERIFY BEFORE CLIENT USE</b>Business details and terms were transcribed from the supplied paper sheet. Review the phone, email, address and terms with RR Creation.</div><dl class="detail-list sectiongap"><div><dt>Business name</dt><dd>${esc(db.settings.name)}</dd></div><div><dt>Phone</dt><dd>${esc(db.settings.phone)}</dd></div><div class="full"><dt>Address</dt><dd>${esc(db.settings.address)}</dd></div><div class="full"><dt>Email</dt><dd>${esc(db.settings.email)}</dd></div><div class="full"><dt>Invoice terms</dt><dd style="white-space:pre-line">${esc(db.settings.terms)}</dd></div></dl></div></section><div><section class="card"><div class="cardhead"><h2>Team access preview</h2></div><div class="cardbody"><p><b>Owner</b> · Full studio and billing interface.</p><p class="sectiongap"><b>Tailor</b> · Customers, fit and production tools.</p><div class="note sectiongap">Role switching demonstrates interface visibility only. No authentication or secure access enforcement is included.</div><button class="link sectiongap" data-action="reset">Reset sample workspace ↗</button></div></section><section class="card sectiongap"><div class="cardhead"><h2>Recent activity</h2></div>${activityList(db.activity.slice(0,5))}</section></div></div>`}
function websitePage(){return heading('Your atelier, beyond the storefront.','A customer-facing preview. Enquiries are not sent.')+`<section class="card"><div class="cardhead"><h2>${esc(db.settings.name)}</h2><span class="eyebrow">SALT LAKE · KOLKATA</span></div><div class="websitehero"><div><div class="eyebrow">TAILORING WITH A PERSONAL TOUCH</div><h1>Made beautifully.<br><i>Made for you.</i></h1><p>Custom blouses, salwar sets and beloved pieces reimagined. A thoughtful fit, from the first measurement to the final stitch.</p><button class="btn" data-action="enquiry">Enquire about a fitting ${ic('arrow')}</button></div><img src="assets/atelier.jpg" alt="Fabric and tailoring tools from the original catalogue"></div><div class="cardbody row"><span>Custom tailoring · Alterations · Redesigns</span><small>${esc(db.settings.address)}</small></div></section>`}
function render(){const owner=isOwner();$('#nav').innerHTML=[['dashboard','Studio overview'],['customers','Customers'],['orders','Orders'],['production','Production board'],['measurements','Measurements'],['creations','Creation archive'],...(owner?[['payments','Invoices & payments'],['quotes','Quotations']]:[]),['website','Studio website'],['settings','Studio settings']].map(([id,label])=>`<a href="#${id}" class="${view===id||(view==='profile'&&id==='customers')||(view==='order'&&id==='orders')?'active':''}">${ic(id)}${label}${id==='orders'?`<em>${db.orders.filter(active).length}</em>`:''}</a>`).join('');$('#crumb').textContent={dashboard:'Studio overview',profile:'Customer workspace',order:'Order workspace'}[view]||view[0].toUpperCase()+view.slice(1);$('#role-note').textContent=owner?'Frontend preview · fictional customer data · saved in this browser':'Tailor interface preview · no real access enforcement · browser-local demo';if(!owner&&(view==='payments'||view==='quotes')){$('#main').innerHTML=empty('Switch to Owner to preview billing.');return}$('#main').innerHTML=view==='dashboard'?dashboard():view==='customers'||view==='measurements'?customersPage():view==='profile'?profile():view==='orders'?ordersPage():view==='production'?production():view==='order'?orderPage():view==='payments'?paymentsPage():view==='creations'?heading('A living archive of your craft.','The fabric, the finish, the story behind every piece.',action('Add creation','creation'))+creationsGrid(db.creations):view==='quotes'?quotesPage():view==='website'?websitePage():settingsPage()}
function route(){const parts=location.hash.slice(1).split('/');view=parts[0]||'dashboard';if(view==='customer')view='profile';currentId=decodeURIComponent(parts[1]||'');filter=view==='orders'?(currentId||'All'):'All';customerTab=view==='profile'?(parts[2]||'overview'):'overview';if(!isOwner()&&customerTab==='payments')customerTab='overview';versionIndex=0;render();window.scrollTo(0,0)}
const field=(name,label,value='',type='text',required=true,extra='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${extra}></label>`;
const area=(name,label,value='',required=false)=>`<label class="field">${label}<textarea name="${name}" ${required?'required':''}>${esc(value)}</textarea></label>`;
const select=(name,label,values,current)=>`<label class="field">${label}<select name="${name}">${values.map(v=>{const [id,text]=Array.isArray(v)?v:[v,v];return `<option value="${esc(id)}" ${id===current?'selected':''}>${esc(text)}</option>`}).join('')}</select></label>`;
const customerSelect=id=>select('customer','Customer',db.customers.map(c=>[c.id,c.name+' · '+c.id]),id||db.customers[0]?.id);
function showDialog(title,body,{wide=false,submit='Save',onSubmit=null,footer=''}={}){$('#modal').classList.toggle('wide',wide);$('#modalbody').innerHTML=`<form id="form"><div class="modalhead"><h2 id="modal-title">${title}</h2><button type="button" class="close" data-close aria-label="Close dialog">×</button></div><div class="formbody">${body}</div><div class="modalfoot"><span class="form-error" id="form-error" role="alert"></span>${footer}<button type="button" class="btn secondary" data-close>${onSubmit?'Cancel':'Close'}</button>${onSubmit?`<button type="submit" class="btn">${submit}</button>`:''}</div></form>`;if(!$('#modal').open)$('#modal').showModal();$('#form').onsubmit=async e=>{e.preventDefault();if(!onSubmit)return;const button=e.submitter;button.disabled=true;$('#form-error').textContent='';try{const data=Object.fromEntries(new FormData(e.target));const result=await onSubmit(data,e.target);if(result!==false)$('#modal').close()}catch(err){$('#form-error').textContent=err.message||'Unable to save. Please review the form.'}finally{button.disabled=false}}}
function requireText(v,label){if(!String(v||'').trim())throw Error(label+' is required.');return v.trim()}
function validateDate(d,label){if(!/^\d{4}-\d{2}-\d{2}$/.test(d)||Number.isNaN(new Date(d+'T12:00:00').getTime()))throw Error('Choose a valid '+label+'.');return d}
function uid(prefix){return prefix+'-'+crypto.randomUUID()}
function newOrderID(){return 'RR-'+(Math.max(4272,...db.orders.map(o=>Number(o.id.replace('RR-',''))||0))+1)}
function newCustomerID(){return 'KS-'+String(Math.max(141,...db.customers.map(c=>Number(c.id.replace('KS-',''))||0))+1).padStart(4,'0')}
function closeAndRoute(hash,message){persist();location.hash=hash;render();toast(message)}
function customerForm(id,edit=false){const c=edit?customer(id):null;showDialog(edit?'Edit customer profile':'A new familiar face',`<div class="formgrid">${field('name','Full name',c?.name||'')}${field('phone','Mobile number',c?.phone||'','tel',false)}${field('ledger','Original ledger number',c?.ledger||'','text',false)}${field('since','Customer since',c?.since||new Date().getFullYear(),'number',true,'min="1900" max="2100" step="1"')}<div class="full">${area('notes','Fit preferences & personal notes',c?.notes||'')}</div></div>`,{submit:edit?'Save profile':'Create customer',onSubmit:f=>{const name=requireText(f.name,'Customer name');if(f.ledger&&db.customers.some(x=>x.id!==c?.id&&x.ledger===f.ledger.trim()))throw Error('That ledger number already belongs to a customer.');let target=c;if(!target){target={id:newCustomerID(),measurements:[]};db.customers.unshift(target)}Object.assign(target,{name,phone:f.phone.trim(),ledger:f.ledger.trim(),since:f.since,notes:f.notes.trim()});log(edit?'Customer profile updated':'Customer added',target.id);closeAndRoute('customer/'+target.id,'Customer record saved.')}})}
function measurementForm(cid){const c=customer(cid),latest=c.measurements[0];const makeFields=(fields,g)=>fields.map((n,i)=>field(g+i,n,latest?.[g]?.[n]??'','number',false,'min="0.1" max="500" step="0.01" data-measurement')).join('');showDialog('A new fitting, every detail',`<div class="note" style="margin-bottom:20px">${esc(c.name)} · All 22 printed fields are available. Leave measurements you haven’t taken blank. Existing orders retain their saved fit.</div><div class="formgrid">${field('date','Fitting date',localDay(),'date')}${field('garment','Garment type',latest?.garment||'Blouse & salwar')}${select('unit','Measurement unit',['in','cm'],latest?.unit||'in')}${select('staff','Recorded by',[...TAILORS,'Owner'],latest?.staff||TAILORS[0])}</div><h3 class="form-section">Upper garment · 14 fields</h3><div class="measure-inputs">${makeFields(UPPER,'upper')}</div><h3 class="form-section">Salwar · 8 fields</h3><div class="measure-inputs">${makeFields(SALWAR,'salwar')}</div>${area('notes','Fitting notes',latest?.notes||'')}`,{wide:true,submit:'Save fitting record',onSubmit:f=>{const upper={},salwar={};for(const [group,fields,target] of [['upper',UPPER,upper],['salwar',SALWAR,salwar]])fields.forEach((n,i)=>{target[n]=f[group+i]===''?'':Number(f[group+i])});if(![...Object.values(upper),...Object.values(salwar)].some(v=>v!==''))throw Error('Enter at least one measurement.');validateDate(f.date,'fitting date');const m={id:uid('MS'),date:f.date,garment:requireText(f.garment,'Garment type'),unit:f.unit,staff:f.staff,notes:f.notes,upper,salwar};c.measurements.unshift(m);log('New '+m.garment+' measurements saved by '+m.staff,c.id);versionIndex=0;customerTab='measurements';commit('New fitting saved. Existing order snapshots are unchanged.')}});let oldUnit=latest?.unit||'in';$('[name="unit"]').onchange=e=>{const next=e.target.value,factor=next==='cm'?2.54:1/2.54;if(next!==oldUnit)$$('[data-measurement]').forEach(input=>{if(input.value!=='')input.value=cash(Number(input.value)*factor)});oldUnit=next}}
function lineMarkup(line={title:'',qty:1,rate:''}){return `<div class="line-item">${field('lineTitle','Particulars',line.title)}${field('lineQty','Qty',line.qty,'number',true,'min="1" max="100" step="1"')}${field('lineRate','Rate (₹)',line.rate,'number',true,'min="0.01" max="1000000" step="0.01"')}<button type="button" class="remove-line" aria-label="Remove garment">×</button></div>`}
function snapshotChoices(cid){const c=customer(cid);return select('snapshot','Use a saved fitting',[["","No measurements recorded / attach later"],...(c?.measurements||[]).map(m=>[m.id,date(m.date)+' · '+m.garment+' · '+m.unit])],c?.measurements[0]?.id||'')}
function orderForm(cid,quoteId){const quote=db.quotes.find(q=>q.id===quoteId);cid=quote?.customer||cid||db.customers[0].id;const c=customer(cid);showDialog('A new piece, a new story',`<div class="formgrid">${customerSelect(cid)}${field('date','Order date',localDay(),'date')}<div id="snapshot-picker">${snapshotChoices(cid)}</div>${field('due','Promised delivery',shiftDay(7),'date')}${field('fitting','Fitting appointment',shiftDay(5),'date',false)}${select('tailor','Assigned tailor',TAILORS,TAILORS[0])}</div><div class="snapshot-label">${ic('settings')}The selected fitting is copied into this order. Future measurement changes won’t affect it.</div><h3 class="form-section">What are we making?</h3><div id="order-lines">${lineMarkup(quote?{title:quote.title,qty:1,rate:quote.amount}:undefined)}</div><button type="button" class="link" id="add-line">+ Add another garment</button><div class="formgrid sectiongap">${select('fabricOwner','Fabric source',['Customer supplied','Studio supplied'], 'Customer supplied')}${field('fabric','Fabric & colour','','text',false)}</div>${area('notes','Design, fit & finishing notes',c?.notes||'')}<div class="order-totals"><span>Order total</span><strong id="draft-total">₹0</strong></div>${isOwner()?`<div class="formgrid">${field('advance','Advance received (₹)',0,'number',true,'min="0" step="0.01"')}${select('method','Payment method',['UPI','Cash','Card','Bank transfer'],'UPI')}</div>`:'<p class="muted">Payment entry is available in the Owner preview.</p>'}`,{wide:true,submit:'Create order',onSubmit:f=>{validateDate(f.date,'order date');validateDate(f.due,'delivery date');if(f.due<f.date)throw Error('Delivery cannot be before the order date.');if(f.fitting&&(f.fitting<f.date||f.fitting>f.due))throw Error('Fitting must be between the order and delivery dates.');const lines=$$('#order-lines .line-item').map(el=>({title:requireText(el.querySelector('[name="lineTitle"]').value,'Particulars'),qty:Number(el.querySelector('[name="lineQty"]').value),rate:cash(el.querySelector('[name="lineRate"]').value)}));if(!lines.length)throw Error('Add at least one garment.');if(lines.some(l=>!Number.isInteger(l.qty)||l.qty<1||!Number.isFinite(l.rate)||l.rate<=0))throw Error('Enter valid quantities and positive rates.');const value=cash(lines.reduce((s,l)=>s+l.qty*l.rate,0)),advance=cash(f.advance||0);if(advance<0||advance>value)throw Error('Advance must be between zero and the order total.');const c=customer(f.customer),m=c.measurements.find(m=>m.id===f.snapshot);const o={id:newOrderID(),customer:c.id,date:f.date,due:f.due,fitting:f.fitting,tailor:f.tailor,stage:'Confirmed',lines,fabric:f.fabric.trim(),fabricOwner:f.fabricOwner,notes:f.notes,snapshot:m?structuredClone(m):null,references:[],alterations:[],payments:advance?[{id:uid('PAY'),amount:advance,date:f.date,method:f.method,reference:'Advance on order'}]:[],events:[],collected:null};db.orders.unshift(o);if(quote){quote.status='Ordered';quote.order=o.id}log('Order confirmed'+(advance?' with '+money(advance)+' advance':''),c.id,o.id);closeAndRoute('order/'+o.id,'Order created. Production and balances are up to date.')}});const recalc=()=>{const sum=$$('#order-lines .line-item').reduce((s,el)=>s+Number(el.querySelector('[name="lineQty"]').value||0)*Number(el.querySelector('[name="lineRate"]').value||0),0);$('#draft-total').textContent=money(sum)};$('#order-lines').addEventListener('input',recalc);$('#order-lines').addEventListener('click',e=>{if(e.target.closest('.remove-line')){if($$('#order-lines .line-item').length===1){toast('Keep at least one garment on the order.');return}e.target.closest('.line-item').remove();recalc()}});$('#add-line').onclick=()=>{$('#order-lines').insertAdjacentHTML('beforeend',lineMarkup());recalc()};$('[name="customer"]').onchange=e=>{$('#snapshot-picker').innerHTML=snapshotChoices(e.target.value);$('[name="notes"]').value=customer(e.target.value)?.notes||''};recalc()}
function editOrderForm(id){const o=order(id);showDialog('Refine the job details',`<div class="formgrid">${field('due','Promised delivery',o.due,'date')}${field('fitting','Fitting date',o.fitting,'date',false)}${select('tailor','Assigned tailor',TAILORS,o.tailor)}${select('fabricOwner','Fabric source',['Customer supplied','Studio supplied'],o.fabricOwner)}</div>${field('fabric','Fabric & colour',o.fabric,'text',false)}${area('notes','Design & finishing notes',o.notes)}`,{submit:'Save job details',onSubmit:f=>{if(f.due<o.date)throw Error('Delivery cannot precede the order date.');if(f.fitting&&(f.fitting<o.date||f.fitting>f.due))throw Error('Fitting must fall between order and delivery dates.');Object.assign(o,f);log('Job details updated',o.customer,o.id);commit('Job details saved.')}})}
function stageForm(id){const o=order(id),next=STAGES[STAGES.indexOf(o.stage)+1];if(!next)return;showDialog(next==='Delivered'?'A happy handover':'Move to '+next,`<div class="note" style="margin-bottom:20px">${o.id} · ${esc(customer(o.customer)?.name)}<br>${esc(o.lines[0].title)}</div>${next==='Fitting'?field('fitting','Fitting appointment',o.fitting||localDay(),'date'):''}${next==='Delivered'?field('collected','Collection date',localDay(),'date'):''}${area('notes',next==='Fitting'?'Fitting instructions':'Progress notes','')}${next==='Delivered'&&balance(o)>0?`<div class="note">${isOwner()?money(balance(o))+' remains unpaid.':'This order has an outstanding payment.'} Delivery does not clear the balance.</div><label class="checkrow"><input type="checkbox" name="confirm" required>Confirm collection with an outstanding balance.</label>`:''}`,{submit:next==='Delivered'?'Confirm delivery':'Move to '+next,onSubmit:f=>{if(next==='Delivered'&&balance(o)>0&&!f.confirm)throw Error('Confirm the outstanding balance before delivery.');if(next==='Delivered'&&f.collected<o.date)throw Error('Collection cannot precede the order date.');if(next==='Fitting'&&(f.fitting<o.date||f.fitting>o.due))throw Error('Update the promised delivery date first if this fitting is outside the order dates.');o.stage=next;if(f.fitting)o.fitting=f.fitting;if(f.collected)o.collected=f.collected;log('Moved to '+next+(f.notes?' · '+f.notes:''),o.customer,o.id);commit(next==='Delivered'?'Delivery recorded. Customer history is up to date.':'Production moved to '+next+'.')}})}
function alterationForm(id){const o=order(id);showDialog('The finishing touches',`<div class="note" style="margin-bottom:20px">Keep a clear record of the adjustment. Alterations are recorded separately; the original measurement snapshot stays unchanged.</div>${area('note','What needs changing?','',true)}${select('stage','Return to stage',['Cutting','Stitching','Fitting'], 'Stitching')}${field('due','Revised delivery date',o.due<localDay()?shiftDay(2):o.due,'date')}`,{submit:'Record alteration',onSubmit:f=>{if(f.due<o.date)throw Error('Delivery cannot precede the order date.');o.alterations.push({date:localDay(),note:requireText(f.note,'Alteration notes'),stage:f.stage});o.stage=f.stage;o.due=f.due;o.collected=null;log('Alteration recorded · '+f.note,o.customer,o.id);commit('Alteration recorded and production updated.')}})}
function paymentForm(id){if(!isOwner())return;const o=order(id);if(balance(o)<=0){toast('This order is already paid in full.');return}showDialog('Record a payment',`<div class="order-totals"><span>${o.id} · Balance due</span><strong>${money(balance(o))}</strong></div><div class="formgrid">${field('amount','Amount received (₹)',balance(o),'number',true,`min="0.01" max="${balance(o)}" step="0.01"`)}${field('date','Payment date',localDay(),'date',true,`min="${o.date}" max="${localDay()}"`)}${select('method','Payment method',['UPI','Cash','Card','Bank transfer'],'UPI')}${field('reference','Reference / note','','text',false)}</div><div class="note">Demo entry only. No money is transferred.</div>`,{submit:'Record payment',onSubmit:f=>{const amount=cash(f.amount);if(!Number.isFinite(amount)||amount<=0||amount>balance(o))throw Error('Payment must be positive and no more than the outstanding balance.');if(f.date<o.date||f.date>localDay())throw Error('Payment date must be between order date and today.');o.payments.push({id:uid('PAY'),amount,date:f.date,method:f.method,reference:f.reference.trim()});log(money(amount)+' payment recorded via '+f.method,o.customer,o.id);commit('Payment recorded. Invoice and customer balance updated.')}})}
async function readPhoto(file){if(!file||!file.size)return '';if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Choose a JPG, PNG or WebP image.');if(file.size>8*1024*1024)throw Error('Choose an image smaller than 8 MB.');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Unable to read image.'));reader.readAsDataURL(file)});return new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>{const scale=Math.min(1,1000/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.75))};image.onerror=()=>reject(Error('The image could not be opened.'));image.src=data})}
function creationForm(cid){showDialog('Add to the creation archive',customerSelect(cid)+field('title','Creation name')+`<div class="formgrid">${field('fabric','Fabric & colour')}${select('type','Creation type',['New creation','Redesign','Alteration'],'New creation')}${field('date','Creation date',localDay(),'date')}<label class="field">Photograph (optional)<input type="file" name="photo" accept="image/jpeg,image/png,image/webp"><small>JPG, PNG or WebP · up to 8 MB.</small></label></div>`+area('notes','Design notes'),{submit:'Save creation',onSubmit:async(f,form)=>{const image=await readPhoto(form.elements.photo.files[0]);db.creations.unshift({id:uid('CR'),customer:f.customer,title:requireText(f.title,'Creation name'),fabric:f.fabric,type:f.type,date:f.date,notes:f.notes,image});log('Creation added: '+f.title,f.customer);commit('Creation saved in the customer archive.')}})}
function referenceForm(id){const o=order(id);if(o.references.length>=6){toast('This demo supports up to six reference images per order.');return}showDialog('Keep the inspiration close',`<label class="field">Design reference<input type="file" name="photo" required accept="image/jpeg,image/png,image/webp"><small>JPG, PNG or WebP · up to 8 MB · saved in this browser only.</small></label>${field('name','Reference description','','text',true)}`,{submit:'Save reference',onSubmit:async(f,form)=>{const data=await readPhoto(form.elements.photo.files[0]);o.references.push({name:f.name,data});log('Design reference added: '+f.name,o.customer,o.id);commit('Reference saved with the order.')}})}
function quoteForm(cid){if(!isOwner())return;showDialog('A new possibility',customerSelect(cid)+field('title','Garment or service')+field('amount','Estimated amount (₹)','','number',true,'min="0.01" max="1000000" step="0.01"')+select('status','Quotation status',['Pending','Follow up'],'Pending'),{submit:'Save quotation',onSubmit:f=>{db.quotes.unshift({id:'QT-'+String(Math.max(0,...db.quotes.map(q=>Number(q.id.replace('QT-',''))||0))+1).padStart(3,'0'),customer:f.customer,title:requireText(f.title,'Garment or service'),amount:cash(f.amount),status:f.status,date:localDay()});log('Quotation created for '+f.title,f.customer);commit('Quotation saved.')}})}
function reminderForm(key){const [type,id]=key.split(':');let text='',cid;if(type==='order'){const o=order(id);cid=o.customer;const c=customer(cid);text=`Hello ${c.name}, this is ${db.settings.name}. ${o.stage==='Ready'?`Your ${o.lines[0].title} (${o.id}) is ready for collection.`:o.fitting===localDay()?`A reminder about your fitting for ${o.lines[0].title} (${o.id}) on ${date(o.fitting)}.`:`We would like to update you on ${o.lines[0].title} (${o.id}), promised for ${date(o.due)}.`} Please contact us to confirm a convenient time.${isOwner()&&balance(o)>0?' The balance on your order is '+money(balance(o))+'.':''}`}else if(type==='quote'){const q=db.quotes.find(q=>q.id===id);cid=q.customer;text=`Hello ${customer(cid)?.name}, following up on your ${q.title} quotation of ${money(q.amount)} from ${db.settings.name}. Let us know when you would like to begin.`}else{const t=(db.legacyTasks||[]).find(t=>String(t.id)===id);cid=t?.customer;text=t?.title||'Follow-up'}showDialog('A thoughtful follow-up',`<div class="note" style="margin-bottom:20px">Message preview only. Nothing is sent to the customer.</div>${area('message','Reminder message',text,true)}<small>For ${esc(customer(cid)?.name||'the customer')}</small>`,{submit:'Mark follow-up reviewed',onSubmit:()=>{if(!db.doneReminders.includes(key))db.doneReminders.push(key);log('Reminder reviewed (not sent)',cid);commit('Reminder reviewed. No message was sent.')}})}
function numberWords(n){const ones=['','One','Two','Three','Four','Five','Six','Seven','Eight','Nine','Ten','Eleven','Twelve','Thirteen','Fourteen','Fifteen','Sixteen','Seventeen','Eighteen','Nineteen'],tens=['','','Twenty','Thirty','Forty','Fifty','Sixty','Seventy','Eighty','Ninety'];const w=x=>x===0?'':x<20?ones[x]:x<100?tens[Math.floor(x/10)]+(x%10?' '+ones[x%10]:''):x<1000?ones[Math.floor(x/100)]+' Hundred'+(x%100?' '+w(x%100):''):x<100000?w(Math.floor(x/1000))+' Thousand'+(x%1000?' '+w(x%1000):''):x<10000000?w(Math.floor(x/100000))+' Lakh'+(x%100000?' '+w(x%100000):''):w(Math.floor(x/10000000))+' Crore'+(x%10000000?' '+w(x%10000000):'');const cents=Math.round(n*100),whole=Math.floor(cents/100),paise=cents%100;return (w(whole)||'Zero')+' Rupees'+(paise?' and '+w(paise)+' Paise':'')+' Only'}
function printHeader(label,id){const s=db.settings;return `<div class="invoice-header"><div><div class="eyebrow">${label}</div><h1>${esc(s.name)}</h1><p>${esc(id)}</p></div><address>${esc(s.address)}<br>${esc(s.phone)}<br>${esc(s.email)}</address></div>`}
function invoiceHTML(o){const c=customer(o.customer),s=db.settings;return `<article class="invoice">${printHeader('BILL / INVOICE',o.id)}<div class="invoice-meta"><div>Bill to<b>${esc(c.name)}</b>${esc(c.phone)}<br>UID ${c.id} · Ledger ${esc(c.ledger||'—')}</div><div>Order date: <b>${date(o.date)}</b>Delivery date: <b>${date(o.due)}</b></div></div><table><thead><tr><th>Sl.</th><th>Particulars</th><th>Qty</th><th>Rate</th><th>Amount</th></tr></thead><tbody>${o.lines.map((l,i)=>`<tr><td>${i+1}</td><td>${esc(l.title)}</td><td>${l.qty}</td><td>${money(l.rate)}</td><td>${money(l.qty*l.rate)}</td></tr>`).join('')}</tbody></table><div class="invoice-totals"><div class="row"><span>Total</span><b>${money(total(o))}</b></div><div class="row"><span>Advance / payments received</span><b>${money(paid(o))}</b></div><div class="row"><strong>Balance</strong><strong>${money(balance(o))}</strong></div></div><p><b>Value in words:</b> ${numberWords(total(o))}</p>${o.payments.length?`<h3 style="margin:25px 0 10px">Payment record</h3><table><thead><tr><th>Date</th><th>Method / reference</th><th>Amount</th></tr></thead><tbody>${o.payments.map(p=>`<tr><td>${date(p.date)}</td><td>${esc(p.method)}${p.reference?' · '+esc(p.reference):''}</td><td>${money(p.amount)}</td></tr>`).join('')}</tbody></table>`:''}<div class="invoice-terms">${esc(s.terms)}</div><div class="signature">For ${esc(s.name)}</div><div class="print-watermark">DEMO INVOICE · SIMULATED TRANSACTIONS · NOT A TAX INVOICE</div></article>`}
function measurePrint(c,m,o=null){return `<article class="invoice">${printHeader(o?'PRODUCTION JOB SHEET':'CUSTOMER MEASUREMENT SHEET',o?.id||c.id)}<div class="invoice-meta"><div><b>${esc(c.name)}</b>Mobile: ${esc(c.phone)}<br>Ledger: ${esc(c.ledger||'—')}</div><div>${o?'Delivery: '+date(o.due)+'<br>Tailor: '+esc(o.tailor):''}<br>Measured: ${m?date(m.date):'Not recorded'} · ${m?.unit||'—'}</div></div>${o?`<p style="margin-bottom:20px"><b>Garments:</b> ${o.lines.map(l=>esc(l.title)+' × '+l.qty).join('; ')}<br><b>Fabric:</b> ${esc(o.fabric)}<br><b>Notes:</b> ${esc(o.notes)}</p>`:''}<div class="measure-print"><div><h2>Upper garment</h2>${measureTable(m,null,'upper')}</div><div><h2>Salwar</h2>${measureTable(m,null,'salwar')}</div></div><div class="invoice-terms">Fitting notes: ${esc(m?.notes||'No measurements recorded.')}</div>${o?.alterations.length?`<div class="invoice-terms">Alterations: ${o.alterations.map(a=>date(a.date)+' — '+esc(a.note)).join('<br>')}</div>`:''}<div class="print-watermark">DEMO RECORD · ${o?'ORDER MEASUREMENT SNAPSHOT':'CUSTOMER FITTING VERSION'}</div></article>`}
function printDialog(title,html){showDialog(title,html,{wide:true,footer:'<button type="button" class="btn" id="print-now">Print / save PDF</button>'});$('#print-now').onclick=()=>{$('#print-area').innerHTML=html;window.print()}}
function searchDialog(){showDialog('Find a familiar face — or a piece in progress',`<input class="search-input" id="global-query" aria-label="Global search" placeholder="Name, phone, ledger or order number…" autofocus><div id="global-results"></div>`);const update=()=>{const q=$('#global-query').value.trim().toLowerCase();const people=db.customers.filter(c=>(c.name+' '+c.phone+' '+c.id+' '+c.ledger).toLowerCase().includes(q)).slice(0,5);const orders=db.orders.filter(o=>(o.id+' '+o.lines.map(l=>l.title).join(' ')+' '+customer(o.customer)?.name).toLowerCase().includes(q)).slice(0,5);$('#global-results').innerHTML=people.map(c=>`<a class="search-result" data-search-route href="#customer/${c.id}"><div><strong>${esc(c.name)}</strong><small>${c.id} · ${esc(c.phone)} · Ledger ${esc(c.ledger||'—')}</small></div>${ic('arrow')}</a>`).join('')+orders.map(o=>`<a class="search-result" data-search-route href="#order/${o.id}"><div><strong>${o.id} · ${esc(o.lines[0].title)}</strong><small>${esc(customer(o.customer)?.name)} · ${o.stage} · ${dueText(o)}</small></div>${ic('arrow')}</a>`).join('')||empty('Nothing found.','Try a name, phone number, ledger number or order ID.')};$('#global-query').oninput=update;update();$('#global-query').focus()}
function settingsForm(){if(!isOwner())return;const s=db.settings;showDialog('The details on every bill',field('name','Business name',s.name)+field('address','Address',s.address)+`<div class="formgrid">${field('phone','Phone',s.phone,'tel')}${field('email','Email',s.email,'email')}</div>`+area('terms','Printed invoice terms',s.terms,true),{submit:'Save business settings',onSubmit:f=>{db.settings={name:requireText(f.name,'Business name'),address:f.address,phone:f.phone,email:f.email,terms:f.terms};log('Business settings updated');commit('Settings saved. New invoice previews use these details.')}})}
function resetForm(){showDialog('Start with a fresh sample workspace?',`<p>Your edits in this version of the demo will be replaced by the fictional RR Creation sample records. The earlier Known State storage remains untouched.</p><div class="note sectiongap">This affects this browser only. Uploaded reference images and demo payments in this version will also be removed.</div>`,{submit:'Reset demo',onSubmit:()=>{db=newSeed();customerTab='overview';versionIndex=0;persist();location.hash='dashboard';render();toast('Original RR Creation sample records restored.')}})}
function tour(){showDialog('A complete customer journey',`<div class="note">A short walkthrough for your RR Creation presentation.</div>${[['Find the customer','Open Priya Sharma and compare her fitting records.'],['Start a repeat order','Select a saved fitting. Add a blouse and salwar with quantities and rates.'],['Take the advance','Record a demo payment. The customer balance and invoice update together.'],['Follow the making','Assign a tailor and move through cutting, stitching and fitting.'],['Make it perfect','Record an alteration and keep the original order measurements intact.'],['Make the handover','Record the final payment, print the invoice and confirm collection.']].map(([t,s],i)=>`<div class="tour-step"><b>${i+1}</b><div><p>${t}</p><small>${s}</small></div></div>`).join('')}`,{footer:`<button type="button" class="btn" data-tour-go>Open Priya’s workspace</button>`})}
function dispatch(act,id){if(act==='customer')customerForm();else if(act==='edit-customer')customerForm(id,true);else if(act==='measurement')measurementForm(id);else if(act==='order')orderForm(id);else if(act==='quote-order'){const q=db.quotes.find(q=>q.id===id);orderForm(q.customer,q.id)}else if(act==='edit-order')editOrderForm(id);else if(act==='stage')stageForm(id);else if(act==='alteration')alterationForm(id);else if(act==='payment')paymentForm(id);else if(act==='creation')creationForm(id);else if(act==='reference')referenceForm(id);else if(act==='quote')quoteForm(id);else if(act==='reminder')reminderForm(id);else if(act==='invoice'&&isOwner())printDialog('Invoice preview · '+id,invoiceHTML(order(id)));else if(act==='job-sheet'){const o=order(id);printDialog('Production job sheet',measurePrint(customer(o.customer),o.snapshot,o))}else if(act==='print-measure'){const c=customer(id);printDialog('Customer measurement sheet',measurePrint(c,c.measurements[versionIndex]))}else if(act==='snapshot'){const o=order(id);showDialog('The fit captured for '+o.id,`<div class="snapshot-label">Read-only snapshot. Recorded ${date(o.snapshot?.date)} · ${o.snapshot?.unit||'—'}</div><div class="measure-grid"><section class="card"><div class="cardhead"><h2>Upper garment</h2></div>${measureTable(o.snapshot,null,'upper')}</section><section class="card"><div class="cardhead"><h2>Salwar</h2></div>${measureTable(o.snapshot,null,'salwar')}</section></div>`,{wide:true})}else if(act==='settings')settingsForm();else if(act==='reset')resetForm();else if(act==='enquiry')showDialog('Let’s make something yours',`<div class="note" style="margin-bottom:20px">Website form preview only. Nothing is submitted or sent.</div>${field('name','Your name')}${field('phone','Mobile number','','tel')}${area('message','What would you like us to make?','',true)}`,{submit:'Preview enquiry',onSubmit:()=>toast('Enquiry preview complete. No message was sent.')})}
document.addEventListener('click',e=>{const t=e.target.closest('[data-action],[data-close],[data-tab],[data-route],[data-filter],[data-search-route],[data-tour-go]');if(!t)return;if(t.hasAttribute('data-close'))$('#modal').close();if(t.dataset.action)dispatch(t.dataset.action,t.dataset.id||'');if(t.dataset.tab){customerTab=t.dataset.tab;versionIndex=0;render()}if(t.dataset.route)location.hash=t.dataset.route;if(t.dataset.filter){filter=t.dataset.filter;render()}if(t.hasAttribute('data-search-route'))$('#modal').close();if(t.hasAttribute('data-tour-go')){$('#modal').close();location.hash='customer/'+(customer('KS-0142')?.id||db.customers[0].id)}});
document.addEventListener('input',e=>{if(e.target.id==='customer-search'){const q=e.target.value.toLowerCase();$('#customer-results').innerHTML=customerTable(db.customers.filter(c=>(c.name+' '+c.phone+' '+c.id+' '+c.ledger).toLowerCase().includes(q)))}});
document.addEventListener('change',e=>{if(e.target.id==='measurement-version'){versionIndex=Number(e.target.value);render()}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();searchDialog()}});
$('#role').onchange=()=>{if(!isOwner()&&customerTab==='payments')customerTab='overview';render()};$('#reset').onclick=resetForm;$('#tour-start').onclick=tour;$('#search-open').onclick=searchDialog;window.addEventListener('hashchange',route);window.addEventListener('afterprint',()=>$('#print-area').innerHTML='');route();if(storageProblem)toast('Stored data could not be loaded. A temporary sample workspace is open; existing storage was not erased.');
